package org.sleepwell.app;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.os.*;
/** Read-only capability hints; only a successful echo test can qualify a current placement. */
final class SonarCapabilities {
 interface Provider {SonarCapabilities read(Context c);}
 static Provider provider=SonarCapabilities::read;
 final boolean microphone,charging;final String issue,support;SonarCapabilities(boolean microphone,boolean charging,String issue,String support){this.microphone=microphone;this.charging=charging;this.issue=issue;this.support=support;}
 boolean allowed(){return microphone&&issue.isEmpty();}
 static boolean external(AudioManager audio){for(AudioDeviceInfo d:audio.getDevices(AudioManager.GET_DEVICES_OUTPUTS)){int t=d.getType();if(t!=AudioDeviceInfo.TYPE_BUILTIN_SPEAKER&&t!=AudioDeviceInfo.TYPE_BUILTIN_EARPIECE&&!(Build.VERSION.SDK_INT>=31&&t==AudioDeviceInfo.TYPE_BUILTIN_SPEAKER_SAFE))return true;}return false;}
 static SonarCapabilities read(Context c){return read(c,false);}
 static SonarCapabilities readNight(Context c,java.util.function.BooleanSupplier owner){if(!owner.getAsBoolean())return new SonarCapabilities(false,false,"The manual recording no longer owns audio.","Unavailable");return read(c,true);}
 private static SonarCapabilities read(Context c,boolean ownTracking){boolean permission=c.checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;BatteryManager battery=c.getSystemService(BatteryManager.class);boolean charging=battery!=null&&battery.isCharging();AudioManager audio=c.getSystemService(AudioManager.class);String issue="",support="Hardware support unverified";if(audio==null)issue="Audio hardware is unavailable.";else{String mic=audio.getProperty(AudioManager.PROPERTY_SUPPORT_MIC_NEAR_ULTRASOUND),speaker=audio.getProperty(AudioManager.PROPERTY_SUPPORT_SPEAKER_NEAR_ULTRASOUND);if("false".equals(mic)||"false".equals(speaker))issue="This phone reports no near-ultrasound microphone or speaker support.";else if("true".equals(mic)&&"true".equals(speaker))support="Phone reports near-ultrasound support; placement still needs testing.";if(issue.isEmpty()&&external(audio))issue="Disconnect headphones and external audio devices before testing.";if(issue.isEmpty()&&audio.getMode()!=AudioManager.MODE_NORMAL)issue="Finish the current call before testing.";if(issue.isEmpty()&&audio.isMusicActive())issue="Stop other audio before testing.";if(issue.isEmpty()&&audio.getStreamVolume(AudioManager.STREAM_MUSIC)==0)issue="Media volume is muted. Adjust it yourself before testing.";}if(issue.isEmpty()&&!charging)issue="Connect a charger before testing contactless sensing.";if(issue.isEmpty()&&(AlarmService.active||(!ownTracking&&TrackingService.running)||Prefs.flag(c,"ringing")))issue="Finish the active alarm or tracking session first.";return new SonarCapabilities(permission,charging,issue,support);}
}
